UNITS = [
    {"id": "PEDS-U145", "ch": 18, "n": 1, "title": "Aneuploidies — Down Syndrome Pathogenesis, Face and Limbs", "sec": "Aneuploidies · p74", "qs": [], "guide": "Aneuploidies Abnormal number of chromosomes. TRISOMIES Presence of three chromosomes in place of a pair. Down Syndrome (Trisomy 21) m/c trisomy. Pathogenesis 1. Maternal meiotic non-disjunction (95%) m/c genetic cause 2. Translocation (4%) t(4;21) t(14;21) 3. Mosaic (1%) abnormal pair of ch.21 with 3 others. Face Brachycephaly, Flat face, Flat occiput, Redundant skin, Low set ears, Flat nose, Brushfield spots, Upslanting palpebral fissures/mongoloid slant, Epicanthal fold, Open mouth with protruding tongue (D/t hypoplastic mandible). Limbs Simian crease (Single transverse palmar crease), 5th/little finger Clinodactyly (Curved finger d/t hypoplasia of phalanx), Foot Sandal gap (↑ed gap between 1st and 2nd toe)."},
    {"id": "PEDS-U146", "ch": 18, "n": 2, "title": "Down Syndrome — Internal Manifestations, Associations, Recurrence Risk", "sec": "Down Syndrome · p75", "qs": [], "guide": "Heart Congenital Heart Defect m/c 40%, Endocardial cushion/AVSD, m/c cause of morbidity/mortality. Brain Low IQ, Hypotonia. GI Intestinal atresia (m/c Duodenum) → obstruction, Hirschsprung/aganglionosis, annular pancreas. Associations 1. Hypothyroidism (congenital/acquired, autoantibodies e.g. Antithyroid peroxidase Ab) 2. Leukemia ALL m/c overall; AML-M7 megakaryoblastic m/c in <3 yrs 3. Presenile Alzheimer's 35-40yrs (Trisomy 21 → Overexpression APP gene → Amyloid ↑ → brain deposition) 4. Atlanto-axial subluxation/instability 10-30% (Upon hyperflexion e.g. sports → sudden spinal cord compression; Dx Lateral X-ray neck; Avoid contact sports). Recurrence risk General 1%; Maternal age >35 yrs up to 4%; Robertsonian translocation parents t(4;21) mother 10% father 5%; t(14;21) 100% 100%."},
    {"id": "PEDS-U147", "ch": 18, "n": 3, "title": "Edwards and Patau Syndromes", "sec": "Edwards Syndrome · p75", "qs": [], "guide": "Edwards Syndrome Trisomy 18 — 2nd m/c trisomy. External Microphthalmos (Short palpebral fissures), Short neck, Limited hip abduction, Clenched hands with overlapping fingers, Prominent heels, Rocker bottom feet, Occiput/back of skull prominent, Dysplastic/malformed ears. Internal CHD >90% VSD > PDA > ASD; Renal horseshoe kidney. Patau Syndrome Trisomy 13 Scalp defects (Aplasia cutis), Microphthalmos, Cleft lip and/or palate, Dysplastic ears, Absent/missing ribs, Undescended testes/cryptorchidism, Clenched hands and polydactyly (Postaxial polydactyly). Heart defects 80-90% VSD > PDA > ASD; CNS Holoprosencephaly."},
    {"id": "PEDS-U148", "ch": 18, "n": 4, "title": "Turner Syndrome — Karyotype and External Features", "sec": "Turner Syndrome · p76", "qs": [], "guide": "Karyotype 45,X0/monosomy X (57%) > Mosaicism (39%) > Partial monosomy X (14%) (monosomy X in some cells) (Ring/iso chromosome X). Gender Female. External Short stature (Adults <145 cm), Lymphedema (May involve foot/hand/neck, Cystic hygroma, Seen during infancy), Neck Web neck + Loose skin folds, Normal IQ, Low hairline, Shield-shaped thorax, Widely spaced nipples, Fold of skin, Shortened metacarpal IV, Small finger nails, Streak ovaries, Cubitus valgus carrying angle >135° (Increased, lateral deviation of limbs at elbow)."},
    {"id": "PEDS-U149", "ch": 18, "n": 5, "title": "Turner Internal Features, Noonan and Klinefelter Syndromes", "sec": "Turner & Noonan · p77", "qs": [], "guide": "Turner internal Heart Bicuspid aortic valve/Coarctation of aorta; Kidney 50% Horseshoe kidney; Delayed puberty & Infertility in adulthood. Pseudo Turner/Noonan Inheritance Autosomal dominant (Males and Females affected); Gene PTPN (Protein tyrosine phosphatase non-Receptor) ch.12q24. Table Turner vs Noonan — Gender Females vs Both; IQ Normal vs Low; Gonadal Streak ovaries vs Cryptorchidism (male); m/c heart Bicuspid aortic valve/Coarctation vs Pulmonary stenosis. Klinefelter Eunuchoid body habitus Taller stature (long limbs), Low (hairline), Reduced facial/axillary hair, Breast development (Gynaecomastia), Cryptorchidism → ↓Testosterone → Delayed progression of puberty; ↑Aromatase Testosterone→Estrogen → breast tissue → persistent → ↑risk breast carcinoma; Long term ↑ Risk extragonadal germ cell tumors anterior mediastinum."},
    {"id": "PEDS-U150", "ch": 18, "n": 6, "title": "Microdeletion Syndromes — DiGeorge and Williams", "sec": "Microdeletion Syndromes · p77", "qs": [], "guide": "Deletion of a tiny part of chromosome → Undetectable on karyotyping. DiGeorge Affected ch.22q11.2; Defective development of 3rd and 4th pharyngeal pouches → Defect in thymus, parathyroid. Features Hypertelorism (Widely separated eyes), Low lying notched ears, Thin upper lip, Small jaw. Associations CATCH-22 C Cardiac conotruncal defects (Tetralogy of Fallot m/c), A Abnormal face, T T cell deficiency (absence of thymus), C Cleft lip/palate, H Hypocalcemia (PTH deficiency), 22 Chromosome 22. Williams 7q11.23 Elfin face (Prominent forehead, Puffiness of eyes and cheeks, Wide mouth); Hypercalcemia; Heart defect Supravalvular aortic stenosis m/c; Low IQ, learning disabilities."},
    {"id": "PEDS-U151", "ch": 18, "n": 7, "title": "Genomic Imprinting Disorders — Prader-Willi", "sec": "Genomic Imprinting · p78", "qs": [], "guide": "Imprinting Silencing. Pathophysiology 1 Gene → 2 Alleles (Active/Inactive) → Genomic imprinting disorders Deletion (active allele) or Disomy (inactive allele). Prader-Willi Genetic defect Chromosome 15q11-13 → Deletion of paternal allele / Disomy of maternal allele. Clinical 1. Massive Obesity ↑Ghrelin → ↑appetite → ↑food intake; 2. Short stature (compared to children of similar age); 3. Small hands and feet; 4. Small eyes Almond shaped; 5. Hypogonadism → Delayed puberty → Low IQ."},
    {"id": "PEDS-U152", "ch": 18, "n": 8, "title": "Angelman Syndrome and Fragile X (Trinucleotide Repeat)", "sec": "Trinucleotide Repeat · p79", "qs": [], "guide": "Angelman AKA happy puppet syndrome. Gene defect 15q11-13 Deletion of maternal allele / Disomy of paternal allele. Neurological ↑incidence of seizures, Hypotonia, Low IQ, Speech defects (Communicate in sign language), Abnormal movements of hands & feet Ataxia. Fragile X (TRD) CGG repeats <55 Normal, >200 TRD; Gene defect FMR1 (Fragile messenger ribonucleoprotein) protein gene. Clinical Large ears, Long face, Prominent chin, Macroorchidism (Large testes) post puberty, ↑Behavioural (ADHD, Autism). Other associations Connective tissue defects (Hyperextensive joints, High arched palate, Mitral valve prolapse MVP), Low IQ."},
]

