RANGES = {145:(1,17),146:(18,38),147:(39,47),148:(48,59),149:(60,73),150:(74,86),151:(87,91),152:(92,102)}
UNIT_RANGES = {1:(1,17),2:(18,38),3:(39,47),4:(48,59),5:(60,73),6:(74,86),7:(87,91),8:(92,102)}
for u in UNITS:
    s,e = UNIT_RANGES[u["n"]]
    u["qs"] = [f"PEDS-C18-{i:03d}" for i in range(s,e+1)]

pages = [q["page"] for q in QUESTIONS]
assert pages == sorted(pages), f"Pages not sorted {pages[:10]}"
assert len(QUESTIONS)==102
assert len(UNITS)==8
for u in UNITS:
    s,e = UNIT_RANGES[u["n"]]
    assert len(u["qs"])==e-s+1
